#include <stdio.h>
#include <string.h>
void revstr(char *c,int length)
{
    char temp;
    if(length==1||length==0)
    return;
    temp=c[0];
    c[0]=c[length-1];
    c[length-1]=temp;
    revstr(c+1,length-2);
}
