#include <stdio.h>
#include <string.h>
void reverse_string(char str1[],char str2[],int k,int i)
{
    if(k<0)
    {
        str2[i]='\0';
        return;
    }
    str2[i]=str1[k];
    reverse_string(str1,str2,k-1,i+1);
}
int main()
{
    int n;
    scanf("%d",&n);
    char str1[n],str2[n];
    for(int i=0;i<n-1;i++)
    {
        scanf("%c",&str1[i]);
    }

    reverse_string(str1,str2,n-1,0);
    for(int i=0;i<n;i++)
    {
        printf("%c",str2[i]);
    }

    return 0;
}

